              setActiveActionsId(null);
          }} className="w-full flex items-center gap-3 px-3 py-2.5 hover:bg-emerald-50 rounded-xl transition-colors text-left group">
              <div className="h-8 w-8 rounded-lg bg-emerald-50 flex items-center justify-center text-emerald-600 group-hover:bg-white shadow-sm"><svg className="h-4 w-4" fill="currentColor" viewBox="0 0 24 24"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L0 24l6.335-1.662c1.72.94 3.659 1.437 5.634 1.437h.005c6.558 0 11.894-5.335 11.897-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg></div>
              <span className="text-[10px] font-black uppercase tracking-widest text-emerald-700">WhatsApp Creds</span>
          </button>
          <div className="my-1 border-t border-slate-100" />
          <button onClick={() => { setIsEditModalOpen(true); setActiveActionsId(null); }} 
              className="w-full flex items-center gap-3 px-3 py-2.5 hover:bg-slate-50 rounded-xl transition-colors text-left group">
              <div className="h-8 w-8 rounded-lg bg-slate-100 flex items-center justify-center text-slate-500 group-hover:bg-white shadow-sm"><svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg></div>
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">Modify Record</span>
          </button>
          <button onClick={() => { if(confirm('Delete client permanently from vault?')) api.deleteClient(selectedClient!.id).then(fetch); setActiveActionsId(null); }} 
              className="w-full flex items-center gap-3 px-3 py-2.5 hover:bg-red-50 rounded-xl transition-colors text-left group">
              <div className="h-8 w-8 rounded-lg bg-red-50 flex items-center justify-center text-red-500 group-hover:bg-white shadow-sm"><svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></div>
              <span className="text-[10px] font-black uppercase tracking-widest text-red-600">Delete Permanently</span>
          </button>
        </div>
      )}

      <GSTClientFormModal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} onSave={handleDataChange} initialData={selectedClient} />

      {/* Login Tool Box Modal */}
      {isLoginBoxOpen && loginToolClient && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-slate-900/80 backdrop-blur-xl p-4 animate-in fade-in duration-200">
           <div className="w-full max-w-lg bg-white rounded-[3rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95 border border-slate-200">
              <div className="p-8 bg-slate-900 text-white flex items-center justify-between">
                 <div className="min-w-0">
                    <p className="text-[10px] font-black uppercase tracking-[0.4em] text-indigo-400 mb-2">Portal Access Utility</p>
                    <h3 className="text-xl font-black uppercase truncate">{loginToolClient.tradeName}</h3>
                 </div>
                 <button onClick={() => setIsLoginBoxOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-white/10 transition-colors"><svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg></button>
              </div>

              <div className="p-10 space-y-8">
                 <div className="space-y-4">
                    <div className="flex items-center justify-between px-2">
                       <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Entity GSTIN</span>
                       <button onClick={() => window.open(`https://services.gst.gov.in/services/searchtp?gstin=${loginToolClient.gstProfile?.gstin}`, '_blank')} className="text-[9px] font-black uppercase text-indigo-600 hover:underline">Verify Identity</button>
                    </div>
                    <div className="bg-slate-50 p-4 rounded-2xl border border-slate-200 flex items-center justify-between">
                       <code className="text-lg font-black text-indigo-600 font-mono tracking-widest uppercase">{loginToolClient.gstProfile?.gstin}</code>
                       <button onClick={() => { copyToClipboard(loginToolClient.gstProfile?.gstin || ''); alert('Copied'); }} className="p-2 text-slate-300 hover:text-indigo-600 transition-colors"><svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M8 5H6a2 2 0 00-2-2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2" /></svg></button>
                    </div>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                       <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-2">Portal User ID</span>
                       <div className="bg-slate-50 p-4 rounded-2xl border border-slate-200 flex items-center justify-between">
                          <span className="text-sm font-black text-slate-900 uppercase truncate">{loginToolClient.gstProfile?.username}</span>
                          <button onClick={() => { copyToClipboard(loginToolClient.gstProfile?.username || ''); alert('Copied'); }} className="p-1.5 text-slate-300 hover:text-indigo-600 transition-colors"><svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2-2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2" /></svg></button>
                       </div>
                    </div>
                    <div className="space-y-2">
                       <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-2">Password</span>
                       <div className="bg-slate-50 p-4 rounded-2xl border border-slate-200 flex items-center justify-between">
                          {isEditingLoginPass ? (
                             <input 
                                autoFocus
                                value={tempPass} 
                                onChange={e => setTempPass(e.target.value)} 
                                onBlur={handleUpdatePassword}
                                onKeyDown={e => e.key === 'Enter' && handleUpdatePassword()}
                                className="bg-white border border-indigo-200 rounded-lg px-2 py-1 text-xs font-black w-full outline-none focus:ring-2 focus:ring-indigo-100"
                             />
                          ) : (
                             <>
                                <span className="text-sm font-black text-indigo-600 tracking-wider truncate">{showLoginPass ? loginToolClient.gstProfile?.password : '••••••••'}</span>
                                <div className="flex gap-1.5">
                                   <button onClick={() => setShowLoginPass(!showLoginPass)} className="p-1 text-slate-300 hover:text-indigo-600">{showLoginPass ? '🙈' : '👁️'}</button>
                                   <button onClick={() => setIsEditingLoginPass(true)} className="p-1 text-slate-300 hover:text-amber-500"><svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg></button>
                                </div>
                             </>
                          )}
                       </div>
                    </div>
                 </div>
              </div>

              <div className="p-8 bg-slate-50 border-t border-slate-100">
                 <button 
                   onClick={() => { copyToClipboard(loginToolClient.gstProfile?.username || ''); window.open('https://services.gst.gov.in/services/login', '_blank'); }}
                   className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-slate-900 transition-all shadow-2xl active:scale-[0.98] flex items-center justify-center gap-3"
                 >
                    Launch Portal & Sync ID
                    <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M10 6H6a2 2 0 00-2-2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
                 </button>
              </div>
           </div>
        </div>
      )}

      {/* Full Detail View Modal */}
      {isDetailModalOpen && selectedClient && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-slate-900/70 backdrop-blur-xl p-4 animate-in fade-in duration-200">
          <div className="w-full max-w-5xl max-h-[95vh] bg-white rounded-[3rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95 border border-slate-200">
            <div className="px-10 py-8 bg-slate-50 border-b border-slate-100 flex items-center justify-between shrink-0">
              <div className="min-w-0">
                 <h2 className="text-2xl font-black text-slate-900 tracking-tight leading-none uppercase truncate">{selectedClient.tradeName || selectedClient.legalName}</h2>
                 <p className="text-sm font-bold text-slate-500 mt-2 uppercase tracking-widest truncate">{selectedClient.legalName}</p>
              </div>
              <div className="flex items-center gap-3 shrink-0">
                <button onClick={() => { if(confirm('Permanently wipe record?')) api.deleteClient(selectedClient.id).then(() => { setIsDetailModalOpen(false); fetch(); }); }} className="h-11 px-6 bg-white border border-red-100 text-red-600 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-red-50 transition-all">Remove</button>
                <button onClick={() => { setIsEditModalOpen(true); setIsDetailModalOpen(false); }} className="h-11 px-10 bg-indigo-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-xl hover:bg-slate-900 transition-all">Modify</button>
                <button onClick={() => setIsDetailModalOpen(false)} className="h-11 w-11 flex items-center justify-center rounded-xl bg-slate-100 hover:bg-slate-200 transition-colors"><svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg></button>
              </div>
            </div>

            <div className="p-10 overflow-y-auto no-scrollbar flex-1 space-y-12">
               <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                  <section className="space-y-6 col-span-1 md:col-span-2">
                     <h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 flex items-center gap-3">Compliance Overview <div className="h-px flex-1 bg-slate-100" /></h4>
                     <div className="grid grid-cols-2 gap-8">
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">GSTIN Identity</p><p className={`text-base font-black font-mono tracking-widest ${selectedClient.gstProfile?.gstStatus === 'Closed' ? 'text-red-600' : 'text-indigo-600'}`}>{selectedClient.gstProfile?.gstin}</p></div>
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Statutory Status</p><p className={`text-base font-black uppercase ${selectedClient.gstProfile?.gstStatus === 'Closed' ? 'text-red-600' : 'text-emerald-600'}`}>{selectedClient.gstProfile?.gstStatus || 'Active'}</p></div>
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Registration Date</p><p className="text-base font-black text-slate-900">{selectedClient.gstProfile?.regDate || '---'}</p></div>
                        {selectedClient.gstProfile?.gstStatus === 'Closed' && (
                           <div><p className="text-[9px] font-black uppercase text-rose-400 mb-1">Cancellation Date</p><p className="text-base font-black text-rose-600">{selectedClient.gstProfile?.cancelDate || '---'}</p></div>
                        )}
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Constitution</p><p className="text-base font-black text-slate-900 uppercase">{selectedClient.gstProfile?.constitution}</p></div>
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Tax Scheme</p><p className="text-base font-black text-slate-900 uppercase">{selectedClient.gstProfile?.regType} ({selectedClient.gstProfile?.filingFreq})</p></div>
                     </div>
                  </section>

                  <section className="space-y-6">
                     <h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 flex items-center gap-3">Financial Hub <div className="h-px flex-1 bg-slate-100" /></h4>
                     <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 space-y-5">
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">Primary Bank</p><p className="text-sm font-black text-slate-900 uppercase">{selectedClient.bankDetails?.bankName || '---'}</p></div>
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">A/C Number</p><p className="text-sm font-black text-slate-900 font-mono tracking-tight">{selectedClient.bankDetails?.accountNo || '---'}</p></div>
                        <div><p className="text-[9px] font-black uppercase text-slate-400 mb-1">IFSC Code</p><p className="text-sm font-black text-indigo-600 font-mono tracking-widest">{selectedClient.bankDetails?.ifsc || '---'}</p></div>
                     </div>
                  </section>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <section className="space-y-6">
                     <h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 flex items-center gap-3">Assigned Personnel <div className="h-px flex-1 bg-slate-100" /></h4>
                     <div className="space-y-3">
                        {selectedClient.gstProfile?.stakeholders.map(s => (
                           <div key={s.id} className="bg-slate-50/50 p-4 rounded-2xl border border-slate-100 flex items-center justify-between">
                              <div>
                                 <p className="text-sm font-black text-slate-900 uppercase">{s.name}</p>
                                 <p className="text-[9px] font-bold text-slate-400 font-mono tracking-widest uppercase mt-0.5">{s.pan}</p>
                              </div>
                              <div className="text-right">
                                 <p className="text-[10px] font-black text-slate-700">{s.mobile}</p>
                              </div>
                           </div>
                        ))}
                     </div>
                  </section>

                  <section className="space-y-6">
                     <h4 className="text-[11px] font-black uppercase tracking-[0.25em] text-indigo-600 flex items-center gap-3">Contacts & History <div className="h-px flex-1 bg-slate-100" /></h4>
                     <div className="grid grid-cols-2 gap-4 mb-4">
                        <div className="bg-indigo-50/30 p-4 rounded-2xl border border-indigo-100/50">
                           <p className="text-[9px] font-black text-indigo-400 uppercase tracking-widest mb-1">Firm Accountant</p>
                           <p className="text-sm font-black text-slate-900 uppercase">{selectedClient.gstProfile?.accountantName || '---'}</p>
                           <p className="text-[10px] font-bold text-slate-500 mt-1">{selectedClient.gstProfile?.accountantMobile || '---'}</p>
                        </div>
                        <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                           <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Entity Primary</p>
                           <p className="text-sm font-black text-slate-900">{selectedClient.mobile}</p>
                           <p className="text-[10px] font-bold text-slate-400 mt-1 lowercase truncate">{selectedClient.email}</p>
                        </div>
                     </div>
                     <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                        <p className="text-[9px] font-black uppercase text-slate-400 mb-2">Internal Office Notes</p>
                        <p className="text-xs font-medium text-slate-600 leading-relaxed italic">{selectedClient.remarks || 'No legacy history documented.'}</p>
                     </div>
                  </section>
               </div>
            </div>

            <footer className="p-8 border-t border-slate-100 bg-slate-50/50 flex justify-between items-center shrink-0">
               <span className="text-[9px] font-black text-slate-300 uppercase tracking-[0.4em]">Archived on {new Date(selectedClient.createdAt || Date.now()).toLocaleDateString()}</span>
               <button onClick={() => setIsDetailModalOpen(false)} className="px-12 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] shadow-2xl hover:bg-slate-900 transition-all">Close Review</button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

export default GstMasterPortfolio;

export interface Message {
  id: string;
  sender: string;
  content: string;
  timestamp: number;
}

export interface MetricData {
  label: string;
  value: number;
  trend: 'up' | 'down' | 'stable';
}

export interface UISettings {
  fontSize: number; // in px, default 16
  fontStyle: 'sans' | 'serif' | 'mono';
}

export interface User {
  id: string;
  username: string;
  user_id: string;
  email_id: string;
  mobile_no?: string;
  firm_name?: string | null;
  gstn?: string | null;
  status: 'online' | 'away' | 'offline';
  avatar?: string; // base64 string for DP
  uiSettings?: UISettings;
}

export type ActiveView = string;

