import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../types';
import { api } from '../../services/api.ts';
import ITClientFormModal from '../Clientform/ITClientFormModal';

interface ItMasterPortfolioProps {
  externalSearch?: string;
  categoryFilter?: string;
  onDataChange?: () => void;
}

const ItMasterPortfolio: React.FC<ItMasterPortfolioProps> = ({ 
  externalSearch = '', 
  categoryFilter = 'All',
  onDataChange
}) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [isItModalOpen, setIsItModalOpen] = useState(false);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await api.getClients();
      setClients(data.filter(c => !!c.itProfile));
    } catch (error) {
      console.error("IT Sync Error:", error);
      setClients([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchClients(); }, []);

  const handleDataChange = () => {
    fetchClients();
    if (onDataChange) onDataChange();
  };

  const getClientDisplayId = (client: Client) => {
    // Sort all IT clients by creation date to get rank
    const itGroup = clients.sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));
    const rank = itGroup.findIndex(c => c.id === client.id) + 1;
    return `IT/${rank.toString().padStart(2, '0')}`;
  };

  const handleDelete = async (id: string) => {
    if (confirm('Permanently remove this IT profile from the firm vault?')) {
      try {
        await api.deleteClient(id);
        handleDataChange();
      } catch (err) {
        alert("Operation failed.");
      }
    }
  };

  const filteredClients = useMemo(() => {
    let list = clients;
    if (categoryFilter !== 'All') {
      list = list.filter(c => c.itProfile?.category === categoryFilter);
    }
    const s = externalSearch.toLowerCase();
    return list.filter(c => 
      c.legalName.toLowerCase().includes(s) || 
      (c.itProfile?.pan || '').toLowerCase().includes(s) ||
      (c.itProfile?.fatherName || '').toLowerCase().includes(s)
    );
  }, [clients, externalSearch, categoryFilter]);

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  if (isLoading) return (
    <div className="flex-1 flex flex-col items-center justify-center p-20 space-y-4">
       <div className="h-10 w-10 border-4 border-slate-100 border-t-emerald-600 rounded-full animate-spin" />
       <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Accessing IT Vault</p>
    </div>
  );

  return (
    <div className="flex-1 flex flex-col min-h-0">
      <div className="overflow-x-auto no-scrollbar flex-1">
        <table className="w-full text-left border-collapse table-fixed min-w-[1100px]">
          <thead className="sticky top-0 z-20">
            <tr className="bg-slate-50 border-b border-slate-100">
              <th className="px-6 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[100px]">ID</th>
              <th className="px-6 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[260px]">Legal Name</th>
              <th className="px-6 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[180px]">PAN No.</th>
              <th className="px-6 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[180px]">Father's Name</th>
              <th className="px-6 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[150px]">Category</th>
              <th className="px-6 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[160px]">Portal Access</th>
              <th className="px-6 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 text-right w-[130px]">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredClients.length === 0 ? (
              <tr>
                <td colSpan={7} className="py-32 text-center text-slate-300 font-black uppercase tracking-widest text-sm">
                  No IT Master Records Found
                </td>
              </tr>
            ) : (
              filteredClients.map((client, idx) => (
                <tr key={client.id} className="hover:bg-emerald-50/20 transition-all group h-[44px]">
                  <td className="px-6 py-[2px] font-black text-emerald-600 font-mono text-[12px] truncate">
                    {getClientDisplayId(client)}
                  </td>
                  <td className="px-6 py-[2px]">
                     <p className="font-black text-slate-900 uppercase truncate text-[12px]">{client.legalName}</p>
                     <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">{client.mobile || '---'}</p>
                  </td>
                  <td className="px-6 py-[2px]">
                    <div className="flex items-center gap-2 group/pan">
                      <span className="font-black text-emerald-600 font-mono tracking-widest uppercase text-[12px]">{client.itProfile?.pan}</span>
                      <button onClick={() => copyToClipboard(client.itProfile?.pan || '')} className="p-1 text-slate-300 hover:text-emerald-600 opacity-0 group-hover/pan:opacity-100 transition-all">
                        <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M8 5H6a2 2 0 00-2-2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2" /></svg>
                      </button>
                    </div>
                  </td>
                  <td className="px-6 py-[2px] text-[12px] font-black text-slate-600 uppercase truncate">{client.itProfile?.fatherName || '---'}</td>
                  <td className="px-6 py-[2px]">
                    <span className="px-2 py-0.5 rounded text-[10px] font-black uppercase tracking-widest bg-slate-100 text-slate-500 border border-slate-200">
                      {client.itProfile?.category}
                    </span>
                  </td>
