const CompositionFiling: React.FC = () => {
  const defaultPeriod = getDefaultPeriod();
  const [clients, setClients] = useState<Client[]>([]);
  const [allClientsBase, setAllClientsBase] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedYear, setSelectedYear] = useState(defaultPeriod.quarterYear);
  const [selectedQuarter, setSelectedQuarter] = useState(defaultPeriod.quarter);

  const { getStatus, toggleStatus, updateDueDate, getDueDate } = useCompositionFilingLogic(selectedYear, selectedQuarter);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await api.getClients();
      setAllClientsBase(data);
      const filtered = data.filter(c => 
        c.status === 'Active Filing' && 
        c.gstProfile?.regType === 'Composition'
      );
      setClients(filtered);
    } finally { setIsLoading(false); }
  };

  useEffect(() => { fetchClients(); }, []);

  const getClientDisplayId = useCallback((client: Client) => {
    if (!client.gstProfile) return '---';
    const isState = client.gstProfile.jurisdictionType === 'State';
    const val = isState ? client.gstProfile.sector : client.gstProfile.range;
    const prefix = isState ? 'S' : 'C';

    const sameGroup = allClientsBase.filter(c => 
      c.gstProfile &&
      c.gstProfile.jurisdictionType === client.gstProfile?.jurisdictionType &&
      (isState ? c.gstProfile.sector === val : c.gstProfile.range === val)
    ).sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));

    const rank = sameGroup.findIndex(c => c.id === client.id) + 1;
    return `${prefix}/${val || '?'}/${rank}`;
  }, [allClientsBase]);

  const filteredClients = useMemo(() => {
    const s = search.toLowerCase();
    return clients.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) ||
      (c.gstProfile?.gstin || '').toLowerCase().includes(s)
    );
  }, [clients, search]);

  const stats = useMemo(() => {
    const total = filteredClients.length;
    const filed = filteredClients.filter(c => getStatus(c.id).cmp08).length;
    return { total, filed };
  }, [filteredClients, getStatus]);

  const copyAndOpen = (username: string) => {
    navigator.clipboard.writeText(username);
    window.open('https://services.gst.gov.in/services/login', '_blank');
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 animate-in fade-in duration-500 max-w-full mx-auto w-full overflow-hidden">
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Comp. Total</p>
            <p className="text-xl font-black text-slate-900 leading-none">{stats.total}</p>
          </div>
          <div className="text-center border-l border-slate-100 pl-6">
            <p className="text-[9px] font-black text-amber-500 uppercase tracking-widest mb-1">CMP-08 Filed</p>
            <p className="text-xl font-black text-amber-600 leading-none">{stats.filed}</p>
          </div>
        </div>

        <div className="relative flex-1 w-full group">
          <input type="text" placeholder="Search composition client..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} className="bg-slate-50 border-none rounded-xl px-4 py-3 text-[11px] font-black uppercase tracking-widest text-slate-600 outline-none cursor-pointer hover:bg-slate-100 transition-all">{YEARS.map(y => <option key={y} value={y}>{y}</option>)}</select>
          <select value={selectedQuarter} onChange={e => setSelectedQuarter(e.target.value)} className="bg-slate-50 border-none rounded-xl px-4 py-3 text-[11px] font-black uppercase tracking-widest text-slate-600 outline-none cursor-pointer hover:bg-slate-100 transition-all">{QUARTERS.map(q => <option key={q} value={q}>{q}</option>)}</select>
          <div className="flex items-center bg-slate-50 rounded-xl px-4 py-3 gap-2 border border-transparent focus-within:border-indigo-100 transition-all">
            <span className="text-[9px] font-black text-slate-400 uppercase whitespace-nowrap">Due:</span>
            <input type="date" value={getDueDate()} onChange={e => updateDueDate(e.target.value)} className="bg-transparent border-none p-0 text-[11px] font-black text-slate-600 outline-none cursor-pointer uppercase" />
          </div>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1100px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-6 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[100px]">ID</th>
                <th className="px-6 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[240px]">Composition Identity</th>
                <th className="px-6 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[200px]">GSTIN</th>
                <th className="px-6 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 text-center w-[130px]">CMP-08 Status</th>
                <th className="px-6 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[160px]">Credentials</th>
                <th className="px-6 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 text-right w-[100px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredClients.map((client, idx) => {
                const st = getStatus(client.id);
                return (
                  <tr key={client.id} className="group hover:bg-indigo-50/20 transition-all text-[12px] h-[44px]">
                    <td className="px-6 py-[2px] font-black text-indigo-400 font-mono text-[11px] truncate">
                      {getClientDisplayId(client)}
                    </td>
                    <td className="px-6 py-[2px]">
                      <p className="font-black text-slate-900 uppercase truncate text-[12px]">{client.tradeName || client.legalName}</p>
                      <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter truncate">{client.legalName}</p>
                    </td>
                    <td className="px-6 py-[2px]">
                      <span className="font-black text-amber-600 font-mono tracking-widest uppercase text-[12px]">{client.gstProfile?.gstin}</span>
                    </td>
                    <td className="px-6 py-[2px] text-center">
                       <button onClick={() => toggleStatus(client.id)} className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all border ${st.cmp08 ? 'bg-emerald-100 text-emerald-700 border-emerald-200' : 'bg-slate-100 text-slate-400 border-slate-200 hover:bg-slate-200'}`}>
                         {st.cmp08 ? 'Filed' : 'Pending'}</button>
                    </td>
                    <td className="px-6 py-[2px]">
                       <div className="flex flex-col">
                         <span className="text-[10px] font-black text-slate-700 uppercase">{client.gstProfile?.username}</span>
                         <span className="text-[8px] font-bold text-slate-300 uppercase tracking-widest">Portal Vault</span>
                       </div>
                    </td>
                    <td className="px-6 py-[2px] text-right whitespace-nowrap">
                       <button onClick={() => copyAndOpen(client.gstProfile?.username || '')} 
                         className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-100 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all shadow-sm flex items-center justify-center ml-auto group-hover:scale-110">
                          <svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
                       </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default CompositionFiling;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Client } from '../../../types';
import { api } from '../../../services/api.ts';
import GSTClientFormModal from '../../Clientform/GSTClientFormModal';
import Loader from '../../../components/Loader';
import { useGSTR4Logic } from './GSTR4logic';
import { YEARS, FY_QUARTERS } from '../GSTReturn/filinglogic/MonthlyFilingLogic';

const GSTR4: React.FC = () => {
  const getPreviousFY = () => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();
    const startYear = currentMonth >= 3 ? currentYear - 1 : currentYear - 2;
    return `${startYear}-${(startYear + 1).toString().slice(-2)}`;
  };

  const [clients, setClients] = useState<Client[]>([]);
  const [allClientsBase, setAllClientsBase] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedYear, setSelectedYear] = useState(getPreviousFY());

  const [statusFilter, setStatusFilter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [isFilterMenuOpen, setIsFilterMenuOpen] = useState(false);

  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [visiblePasswords, setVisiblePasswords] = useState<Set<string>>(new Set());

  const [editingPasswordId, setEditingPasswordId] = useState<string | null>(null);
  const [newPasswordValue, setNewPasswordValue] = useState('');

  const [showPassInModal, setShowPassInModal] = useState(false);
  const [isEditingPassInModal, setIsEditingPassInModal] = useState(false);
  const [modalPassValue, setModalPassValue] = useState('');

  const { getStatus, toggleStatus, updateDueDate, getDueDate } = useGSTR4Logic(selectedYear);

  const cmp08Data = useMemo(() => {
    const saved = localStorage.getItem('clientify_composition_filing_v3');
    return saved ? JSON.parse(saved) : {};
  }, [selectedYear]);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await api.getClients();
      setAllClientsBase(data);
      const filtered = data.filter(c => 
        c.gstProfile?.regType === 'Composition' &&
        (c.status === 'Active Filing' || c.status === 'Active')
      );
      setClients(filtered);
    } catch (err) {
      console.error("GSTR-4 Sync Failed:", err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const getClientDisplayId = useCallback((client: Client) => {
    if (!client.gstProfile) return '---';
    const isState = client.gstProfile.jurisdictionType === 'State';
    const val = isState ? client.gstProfile.sector : client.gstProfile.range;
    const prefix = isState ? 'S' : 'C';

    const sameGroup = allClientsBase.filter(c => 
      c.gstProfile &&
      c.gstProfile.jurisdictionType === client.gstProfile?.jurisdictionType &&
      (isState ? c.gstProfile.sector === val : c.gstProfile.range === val)
    ).sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));

    const rank = sameGroup.findIndex(c => c.id === client.id) + 1;
    return `${prefix}/${val || '?'}/${rank}`;
  }, [allClientsBase]);

  const saveQuickPassword = async (client: Client) => {
    try {
      const updated = { ...client, gstProfile: { ...client.gstProfile!, password: newPasswordValue } };
      await api.saveClient(updated);
      setClients(prev => prev.map(c => c.id === client.id ? (updated as Client) : c));
      setEditingPasswordId(null);
    } catch (err) { 
      alert("Portal Password update failed."); 
    }
  };

  const saveQuickPasswordFromModal = async () => {
    if (!selectedClient) return;
    try {
      const updatedClient = {
        ...selectedClient,
        gstProfile: { ...selectedClient.gstProfile!, password: modalPassValue }
      };
      await api.saveClient(updatedClient);
      setSelectedClient(updatedClient as Client);
      setIsEditingPassInModal(false);
      fetchClients();
    } catch (err) { 
      alert("Update failed."); 
    }
  };

  const filteredClients = useMemo(() => {
    let list = clients.filter(c => 
      (c.legalName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.tradeName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.gstProfile?.gstin || '').toLowerCase().includes(search.toLowerCase())
    );

    if (statusFilter !== 'All') {
      list = list.filter(c => statusFilter === 'Filed' ? getStatus(c.id).filed : !getStatus(c.id).filed);
    }
    return list;
  }, [clients, search, statusFilter, getStatus]);

  const stats = useMemo(() => {
    const total = filteredClients.length;
    const filedCount = filteredClients.filter(c => getStatus(c.id).filed).length;
    return { total, filedCount };
  }, [filteredClients, getStatus]);

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const shareViaWhatsApp = (text: string) => {
    const url = `https://api.whatsapp.com/send?phone=&text=${encodeURIComponent(text)}`;
    window.open(url, '_blank');
  };

  const getCredText = (client: Client) => `*GST Credentials for ${client.tradeName || client.legalName}*\n\n*GSTIN:* ${client.gstProfile?.gstin}\n*Username:* ${client.gstProfile?.username}\n*Password:* ${client.gstProfile?.password}\n\n_Generated via Clientify Vault_`;

  const getFullShareText = (client: Client) => {
    const stakeholders = client.gstProfile?.stakeholders?.map(s => `• ${s.name} (${s.pan})`).join('\n') || 'None';
    return `*Clientify: GSTR-4 Annual Return Share*\n\n*Trade Name:* ${client.tradeName}\n*Legal Name:* ${client.legalName}\n*GSTIN:* ${client.gstProfile?.gstin}\n*Mobile:* ${client.mobile}\n*Email:* ${client.email}\n\n*Login Credentials:*\n*Username:* ${client.gstProfile?.username}\n*Password:* ${client.gstProfile?.password}\n\n*Personnel:*\n${stakeholders}`;
  };

  const handleExport = () => {
    const csvHeaders = [
      "ID",
      "Trade Name",
      "Legal Name",
      "GSTIN",
      "User ID",
      "Password",
      "CMP-08 Q1",
      "CMP-08 Q2",
      "CMP-08 Q3",
      "CMP-08 Q4",
      "GSTR-4 Status",
      "Filing Date"
    ].join(",");

    const csvRows = filteredClients.map((client, index) => {
      const gstr4Status = getStatus(client.id);
      const qStatuses = FY_QUARTERS.map(q => {
        const periodKey = `${selectedYear}_${q}`;
        const periodData = cmp08Data[periodKey];
        return (periodData && periodData[client.id]?.cmp08) ? "FILED" : "PENDING";
      });

      const rowValues = [
        getClientDisplayId(client),
        client.tradeName || "N/A",
        client.legalName || "N/A",
        client.gstProfile?.gstin || "N/A",
        client.gstProfile?.username || "N/A",
        client.gstProfile?.password || "N/A",
        ...qStatuses,
        gstr4Status.filed ? "FILED" : "PENDING",
        gstr4Status.date || "N/A"
      ];

      return rowValues.map(val => {
        const strValue = String(val).replace(/"/g, '""');
        return strValue.includes(',') ? `"${strValue}"` : strValue;
      }).join(",");
    }).join("\n");

    const fullCsvContent = csvHeaders + "\n" + csvRows;
    const blob = new Blob([fullCsvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `GSTR4_Audit_Sheet_${selectedYear}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 animate-in fade-in duration-500 max-w-full mx-auto w-full overflow-hidden">
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">FY {selectedYear}</p>
            <p className="text-xl font-black text-slate-900 leading-none">{stats.total}</p>
          </div>
          <div className="text-center border-l border-slate-100 pl-6">
            <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mb-1">GSTR-4 Filed</p>
            <p className="text-xl font-black text-indigo-600 leading-none">{stats.filedCount}</p>
          </div>
        </div>

        <div className="relative flex-1 w-full group">
          <input type="text" placeholder="Search composition entity or GSTIN..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <div className="flex bg-slate-50 rounded-xl p-1">
             <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} 
               className="bg-transparent border-none rounded-lg px-4 py-2 text-[11px] font-black uppercase tracking-widest text-slate-600 outline-none cursor-pointer">
               {YEARS.map(y => <option key={y} value={y}>FY {y}</option>)}
             </select>
          </div>

          <div className="flex items-center bg-slate-50 rounded-xl px-4 py-3 gap-2 border border-transparent focus-within:border-indigo-100 transition-all">
            <span className="text-[9px] font-black text-slate-400 uppercase whitespace-nowrap">Due:</span>
            <input type="date" value={getDueDate()} onChange={e => updateDueDate(e.target.value)} className="bg-transparent border-none p-0 text-[11px] font-black text-slate-600 outline-none cursor-pointer uppercase" />
          </div>

          <button onClick={handleExport} className="h-11 px-5 flex items-center justify-center bg-slate-900 text-white rounded-xl shadow-lg hover:bg-emerald-600 transition-all gap-2" title="Export to CSV">
            <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4 4m4-4V4" /></svg>
            <span className="text-[10px] font-black uppercase tracking-widest">Export CSV</span>
          </button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1300px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[100px]">ID</th>
                <th className="px-4 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[160px]">Trade Name</th>
                <th className="px-4 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[180px]">Legal Name</th>
                <th className="px-4 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[190px]">GSTIN</th>

                <th className="px-4 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 text-center w-[120px]">
                  CMP-08
