import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { LitigationRecord, Client, LitigationStatus } from '../../../types';
import { api } from '../../../services/api.ts';
import Loader from '../../../components/Loader';
import NoticeForm from '../../Clientform/NoticeForm';

const NoticePending: React.FC = () => {
  const [records, setRecords] = useState<LitigationRecord[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [selectedRecord, setSelectedRecord] = useState<Partial<LitigationRecord> | null>(null);

  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [viewingRecord, setViewingRecord] = useState<LitigationRecord | null>(null);
  const [activeStatusMenuId, setActiveStatusMenuId] = useState<string | null>(null);
  const [sectionFilter, setSectionFilter] = useState('All');
  const [daysLeftFilter, setDaysLeftFilter] = useState<'All' | 'Critical' | 'Healthy'>('All');
  const [activeHeaderFilter, setActiveHeaderFilter] = useState<'section' | 'days' | null>(null);

  const fetchAll = async () => {
    setIsLoading(true);
    try {
      const [recs, clis] = await Promise.all([api.getLitigationRecords(), api.getClients()]);
      setRecords(recs.filter(r => r.category === 'Notice' && r.status === 'Pending'));
      setClients(clis);
    } catch (err) { console.error("Failed to sync notice vault:", err); } finally { setIsLoading(false); }
  };

  useEffect(() => { fetchAll(); }, []);

  const getClientDisplayId = useCallback((clientId: string) => {
    const client = clients.find(c => c.id === clientId);
    if (!client) return '---';

    if (client.gstProfile) {
      const isState = client.gstProfile.jurisdictionType === 'State';
      const val = isState ? client.gstProfile.sector : client.gstProfile.range;
      const prefix = isState ? 'S' : 'C';
      const sameGroup = clients.filter(c => 
        c.gstProfile &&
        c.gstProfile.jurisdictionType === client.gstProfile?.jurisdictionType &&
        (isState ? c.gstProfile.sector === val : c.gstProfile.range === val)
      ).sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));
      const rank = sameGroup.findIndex(c => c.id === client.id) + 1;
      return `${prefix}/${val || '?'}/${rank}`;
    } else if (client.itProfile) {
      const itGroup = clients.filter(c => !!c.itProfile).sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));
      const rank = itGroup.findIndex(c => c.id === client.id) + 1;
      return `IT/${rank.toString().padStart(2, '0')}`;
    }
    return '---';
  }, [clients]);

  const handleSave = async (data: Partial<LitigationRecord>) => {
    if (!data.clientId || !data.referenceNo) { alert("Missing Client or Reference No."); return; }
    await api.saveLitigationRecord({ ...data, category: 'Notice' });
    setIsModalOpen(false); setIsViewModalOpen(false); fetchAll();
  };

  const updateRecordStatus = async (record: LitigationRecord, newStatus: LitigationStatus) => {
    try {
      const updated = { ...record, status: newStatus };
      if (newStatus === 'Filed') updated.filedDate = new Date().toISOString().split('T')[0];
      await api.saveLitigationRecord(updated);
      fetchAll();
    } catch (err) { alert("Status update failed."); }
    setActiveStatusMenuId(null);
  };

  const handleDelete = async (id: string) => {
    if (confirm('Permanently remove this notice record from the secure vault?')) {
      try { await api.delete(`/items/${id}`); fetchAll(); } catch (err) { alert("Deletion failed."); }
    }
  };

  const formatDisplayDate = (dateStr?: string) => {
    if (!dateStr) return '---';
    const parts = dateStr.split('-');
    if (parts.length !== 3) return dateStr;
    const [y, m, d] = parts;
    return `${d}-${m}-${y}`;
  };

  const getDaysLeft = (dueDate: string) => {
    const due = new Date(dueDate);
    due.setHours(0, 0, 0, 0);
    const now = new Date();
    now.setHours(0, 0, 0, 0);
    const diff = due.getTime() - now.getTime();
    return Math.round(diff / (1000 * 60 * 60 * 24));
  };

  const sections = useMemo(() => Array.from(new Set(records.map(r => r.section).filter(Boolean))).sort(), [records]);

  const filteredRecords = useMemo(() => {
    const s = search.toLowerCase();
    let list = records.filter(r => {
      const client = clients.find(c => c.id === r.clientId);
      return (r.clientName || '').toLowerCase().includes(s) || 
             (r.referenceNo || '').toLowerCase().includes(s) ||
             (client?.gstProfile?.gstin || '').toLowerCase().includes(s);
    });
    if (sectionFilter !== 'All') list = list.filter(r => r.section === sectionFilter);
    if (daysLeftFilter !== 'All') {
      list = list.filter(r => {
        const dl = getDaysLeft(r.dueDate);
        return daysLeftFilter === 'Critical' ? dl <= 7 : dl > 7;
      });
    }
    return list;
  }, [records, clients, search, sectionFilter, daysLeftFilter]);

  if (isLoading) return <Loader />;

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 h-full flex flex-col space-y-4 overflow-hidden">

      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Live Notices</p>
            <p className="text-xl font-black text-slate-900 leading-none">{records.length}</p>
          </div>
        </div>

        <div className="relative flex-1 w-full group">
          <input 
            type="text" 
            placeholder="Search by Trade Name, GSTIN or Order Reference..." 
            value={search} 
            onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" 
          />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <button 
          onClick={() => { setSelectedRecord(null); setIsModalOpen(true); }}
          className="bg-indigo-600 text-white font-black uppercase tracking-widest px-8 h-11 rounded-xl shadow-lg hover:bg-slate-900 transition-all text-xs flex items-center gap-2 shrink-0"
        >
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          Record Notice
        </button>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1400px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[100px]">ID</th>
                <th className="px-4 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[220px]">Trade Name</th>
                <th className="px-4 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[180px]">GSTIN</th>
                <th className="px-4 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[140px] relative">
                  <div className="flex items-center gap-1">Section <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'section' ? null : 'section')} className="p-1 rounded shadow-sm"><svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg></button></div>
                  {activeHeaderFilter === 'section' && (
                    <div className="absolute top-full left-0 mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                      <button onClick={() => { setSectionFilter('All'); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${sectionFilter === 'All' ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>All</button>
                      {sections.map(s => <button key={s} onClick={() => { setSectionFilter(s); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${sectionFilter === s ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>U/s {s}</button>)}
                    </div>
                  )}
                </th>
                <th className="px-4 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[150px]">Tax Period</th>
                <th className="px-4 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[120px]">Notice Date</th>
                <th className="px-4 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[150px] relative">
                  <div className="flex items-center gap-1">Deadline <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'days' ? null : 'days')} className="p-1 rounded shadow-sm"><svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg></button></div>
                  {activeHeaderFilter === 'days' && (
                    <div className="absolute top-full left-0 mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                      {['All', 'Critical', 'Healthy'].map(opt => <button key={opt} onClick={() => { setDaysLeftFilter(opt as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${daysLeftFilter === opt ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>{opt}</button>)}
                    </div>
                  )}
                </th>
                <th className="px-4 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 text-center w-[160px]">Status</th>
                <th className="px-4 py-5 text-[14px] font-bold uppercase tracking-widest text-slate-900 text-right w-[120px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredRecords.length === 0 ? (
                <tr><td colSpan={10} className="py-32 text-center text-slate-300 font-black uppercase tracking-[0.2em] text-sm">No Pending Notices in Vault</td></tr>
              ) : (
                filteredRecords.map((rec, idx) => {
                  const dl = getDaysLeft(rec.dueDate);
                  const isOverdue = dl < 0;
                  const isCritical = dl <= 7 && dl >= 0;
                  return (
                    <tr key={rec.id} className="hover:bg-slate-50/50 transition-all group h-[44px]">
                      <td className="px-4 py-[2px] font-black text-indigo-400 font-mono text-[11px] truncate">
                        {getClientDisplayId(rec.clientId)}
                      </td>
                      <td className="px-4 py-[2px]">
                        <p className="text-[12px] font-black text-slate-900 uppercase truncate" title={rec.clientName}>{rec.clientName}</p>
                        <p className="text-[8px] font-bold text-slate-400 uppercase truncate">{rec.referenceNo}</p>
                      </td>
                      <td className="px-4 py-[2px] text-[12px] font-black text-indigo-600 font-mono tracking-widest">{clients.find(c => c.id === rec.clientId)?.gstProfile?.gstin || 'N/A'}</td>
                      <td className="px-4 py-[2px] text-[12px] font-black text-slate-600 uppercase">{rec.section ? `U/s ${rec.section}` : '---'}</td>
                      <td className="px-4 py-[2px] text-[12px] font-black text-slate-700 uppercase">{rec.taxPeriod || '---'}</td>
                      <td className="px-4 py-[2px] text-[12px] font-black text-slate-500 uppercase">{formatDisplayDate(rec.issuedDate)}</td>
                      <td className="px-4 py-[2px]">
                         <div className="flex items-center gap-1.5">
                            <div className={`h-1.5 w-1.5 rounded-full ${isOverdue || isCritical ? 'bg-red-500 animate-pulse' : 'bg-amber-400'}`} />
                            <span className={`text-[12px] font-black ${isOverdue || isCritical ? 'text-red-500' : 'text-slate-700'}`}>
                              {dl < 0 ? `${Math.abs(dl)} Overdue` : `${dl} Days`}
                            </span>
                         </div>
                      </td>
                      <td className="px-4 py-[2px] text-center relative overflow-visible">
                         <button onClick={() => setActiveStatusMenuId(activeStatusMenuId === rec.id ? null : rec.id)} className={`w-full px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest border transition-all flex items-center justify-between ${isOverdue ? 'bg-red-50 text-red-700 border-red-100' : 'bg-amber-50 text-amber-700 border-amber-100'}`}>
                            {isOverdue ? 'Overdue' : 'Pending'} <svg className="h-3 w-3 ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
                         </button>
                         {activeStatusMenuId === rec.id && (
                           <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95 text-left">
                              <button onClick={() => updateRecordStatus(rec, 'Filed')} className="w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg hover:bg-emerald-50 text-emerald-600">Mark Filed</button>
                           </div>
                         )}
                      </td>
                      <td className="px-4 py-[2px] text-right whitespace-nowrap">
                         <div className="flex items-center justify-end gap-2">
                            <button onClick={() => { setViewingRecord(rec); setIsViewModalOpen(true); }} className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 transition-all flex items-center justify-center shadow-sm">
                               <svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>
                            </button>
                         </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Detail Modals kept as is */}
      <NoticeForm isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSave} clients={clients} category="Notice" initialData={selectedRecord} />
    </div>
  );
};

export default NoticePending;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Client, ClientStatus } from '../../types';
import { api } from '../../services/api.ts';
import ITClientFormModal from '../Clientform/ITClientFormModal';

interface ItMasterPortfolioProps {
  externalSearch?: string;
  onDataChange?: () => void;
}

const ItMasterPortfolio: React.FC<ItMasterPortfolioProps> = ({ 
  externalSearch = '', 
  onDataChange
}) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);

  // Filters
  const [statusFilter, setStatusFilter] = useState<string>('All');
  const [isStatusFilterOpen, setIsStatusFilterOpen] = useState(false);

  // Password Visibility State
  const [visiblePasswords, setVisiblePasswords] = useState<Set<string>>(new Set());

  // Actions Menu State (Fixed Positioning)
  const [activeActionsId, setActiveActionsId] = useState<string | null>(null);
  const [menuPosition, setMenuPosition] = useState({ top: 0, left: 0 });
  const actionsRef = useRef<HTMLDivElement>(null);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await api.getClients();
      setClients(data.filter(c => !!c.itProfile));
    } catch (error) {
      console.error("IT Sync Error:", error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchClients(); }, []);

  // Handle closing menu on click outside or scroll
  useEffect(() => {
    const handleClose = (event: any) => {
      if (actionsRef.current && !actionsRef.current.contains(event.target as Node)) {
        setActiveActionsId(null);
      }
    };
    const handleScroll = () => setActiveActionsId(null);

    if (activeActionsId) {
      document.addEventListener('mousedown', handleClose);
      window.addEventListener('scroll', handleScroll, true);
    }
    return () => {
      document.removeEventListener('mousedown', handleClose);
      window.removeEventListener('scroll', handleScroll, true);
    };
  }, [activeActionsId]);

  const handleDataChange = () => {
    fetchClients();
    if (onDataChange) onDataChange();
  };

  const getClientDisplayId = (client: Client) => {
    const itGroup = clients.slice().sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));
    const rank = itGroup.findIndex(c => c.id === client.id) + 1;
    return `IT/${rank.toString().padStart(2, '0')}`;
  };

  const filteredClients = useMemo(() => {
    let list = clients;
    if (statusFilter !== 'All') {
      list = list.filter(c => c.status === statusFilter);
    }
    const s = externalSearch.toLowerCase();
    return list.filter(c => 
      c.legalName.toLowerCase().includes(s) || 
      (c.itProfile?.pan || '').toLowerCase().includes(s) ||
      (c.itProfile?.fatherName || '').toLowerCase().includes(s) ||
      (c.mobile || '').includes(s)
    );
  }, [clients, externalSearch, statusFilter]);

  const togglePassword = (id: string) => {
    setVisiblePasswords(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const shareViaWhatsApp = (text: string) => {
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

  const openActionsMenu = (e: React.MouseEvent, client: Client) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setMenuPosition({ 
      top: rect.bottom + window.scrollY + 8, 
      left: rect.right - 256 
    });
    setActiveActionsId(client.id);
    setSelectedClient(client);
  };

  if (isLoading) return (
    <div className="flex-1 flex flex-col items-center justify-center p-20 space-y-4">
       <div className="h-10 w-10 border-4 border-slate-100 border-t-emerald-600 rounded-full animate-spin" />
       <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Accessing IT Vault</p>
    </div>
  );

  return (
    <div className="w-full h-full flex flex-col min-h-0">
      <div className="overflow-x-auto no-scrollbar flex-1 w-full">
        <table className="w-full text-left border-collapse table-fixed min-w-[1300px]">
          <thead className="sticky top-0 z-20">
            <tr className="bg-slate-50 border-b border-slate-200 shadow-sm">
              <th className="px-[5.5px] py-3 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[100px]">ID no.</th>
              <th className="px-[5.5px] py-3 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[240px]">Name</th>
              <th className="px-[5.5px] py-3 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[200px]">Father Name</th>
              <th className="px-[5.5px] py-3 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[140px]">Mobile No.</th>
              <th className="px-[5.5px] py-3 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[160px]">Pan No.</th>
              <th className="px-[5.5px] py-3 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[160px]">Password</th>
              <th className="px-[5.5px] py-3 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[120px] relative">
                <div className="flex items-center gap-1">
                  Status
                  <button onClick={() => setIsStatusFilterOpen(!isStatusFilterOpen)} className="p-1 hover:bg-slate-200 rounded transition-colors">
                    <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
                  </button>
                </div>
                {isStatusFilterOpen && (
                  <div className="absolute top-full left-0 mt-1 w-32 bg-white border border-slate-200 rounded-xl shadow-xl z-[400] p-1 animate-in zoom-in-95">
                    {['All', 'Active', 'Inactive'].map(f => (
                      <button key={f} onClick={() => { setStatusFilter(f); setIsStatusFilterOpen(false); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${statusFilter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>{f}</button>
                    ))}
                  </div>
                )}
              </th>
              <th className="px-[5.5px] py-3 text-[14px] font-bold uppercase tracking-widest text-slate-900 text-right w-[110px]">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredClients.length === 0 ? (
              <tr><td colSpan={8} className="py-32 text-center text-slate-300 font-black uppercase tracking-widest text-sm">No IT master records found</td></tr>
            ) : (
              filteredClients.map((client, idx) => (
                <tr key={client.id} className="hover:bg-emerald-50/10 transition-all group border-b border-slate-50 last:border-0 h-[44px]">
                  <td className="px-[5.5px] py-[2px] font-black text-emerald-600 font-mono text-[12px] truncate" title={getClientDisplayId(client)}>
                    {getClientDisplayId(client)}
                  </td>
                  <td className="px-[5.5px] py-[2px]">
                     <p className="font-black text-slate-900 uppercase truncate text-[12px]" title={client.legalName}>{client.legalName}</p>
                  </td>
                  <td className="px-[5.5px] py-[2px]">
                     <p className="font-bold text-slate-600 uppercase truncate text-[12px]" title={client.itProfile?.fatherName}>{client.itProfile?.fatherName || '---'}</p>
                  </td>
                  <td className="px-[5.5px] py-[2px]">
                     <p className="font-black text-slate-500 text-[12px]">{client.mobile || '---'}</p>
                  </td>
                  <td className="px-[5.5px] py-[2px]">
                     <div className="flex items-center gap-2 group/pan">
                        <span className="font-black font-mono tracking-widest uppercase text-[12px] text-emerald-600">{client.itProfile?.pan}</span>
                        <button 
                           onClick={() => { copyToClipboard(client.itProfile?.pan || ''); }}
                           className="h-6 w-6 rounded bg-emerald-50 text-emerald-600 hover:bg-emerald-600 hover:text-white transition-all flex items-center justify-center opacity-0 group-hover/pan:opacity-100 shadow-sm border border-emerald-100"
                           title="Copy PAN"
                        >
                           <svg className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M8 5H6a2 2 0 00-2-2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2" /></svg>
                        </button>
                     </div>
                  </td>
                  <td className="px-[5.5px] py-[2px]">
                     <div className="flex items-center gap-2 group/pass">
                        <span className="font-black text-slate-400 text-[12px] tracking-widest">
                           {visiblePasswords.has(client.id) ? client.itProfile?.password : '••••••••'}
                        </span>
                        <button onClick={() => togglePassword(client.id)} className="p-1 text-slate-300 hover:text-indigo-600 opacity-0 group-hover/pass:opacity-100 transition-all">
                           {visiblePasswords.has(client.id) ? '🙈' : '👁️'}
                        </button>
                     </div>
                  </td>
                  <td className="px-[5.5px] py-[2px]">
                     <span className={`px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-tighter border ${
                       client.status === 'Active' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-slate-50 text-slate-400 border-slate-200'
                     }`}>
                       {client.status}
                     </span>
                  </td>
                  <td className="px-[5.5px] py-[2px] text-right overflow-visible">
                     <div className="flex items-center justify-end gap-1">
                        <button 
                          onClick={() => { setSelectedClient(client); setIsDetailModalOpen(true); }}
                          className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center shadow-sm"
                          title="View Profile"
                        >
                           <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>
                        </button>

                        <button 
                          onClick={(e) => openActionsMenu(e, client)}
                          className={`h-8 w-8 rounded-lg border transition-all flex items-center justify-center shadow-sm ${activeActionsId === client.id ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-slate-50 border-slate-200 text-slate-400 hover:text-indigo-600 hover:bg-white'}`}
                        >
                           <svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z" /></svg>
                        </button>
                     </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Global Actions Menu - Fixed Positioned */}
      {activeActionsId && selectedClient && (
        <div 
          ref={actionsRef}
          style={{ top: menuPosition.top, left: menuPosition.left }}
          className="fixed w-64 bg-white border border-slate-200 rounded-[1.5rem] shadow-2xl z-[9999] p-2 animate-in zoom-in-95 origin-top-right overflow-hidden text-left"
        >
          <div className="px-3 py-2 border-b border-slate-50 mb-1">
             <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">IT Operations</p>
             <p className="text-[10px] font-black text-slate-900 truncate uppercase mt-0.5">{selectedClient.legalName}</p>
          </div>
          <button onClick={() => { 
              copyToClipboard(selectedClient!.itProfile?.username || ''); 
              window.open('https://eportal.incometax.gov.in/iec/foservices/#/login', '_blank'); 
              setActiveActionsId(null); 
          }} className="w-full flex items-center gap-3 px-3 py-2.5 hover:bg-indigo-50 rounded-xl transition-colors text-left group">
              <div className="h-8 w-8 rounded-lg bg-indigo-50 flex items-center justify-center text-indigo-600 group-hover:bg-white shadow-sm"><svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg></div>
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-700">IT Portal Login</span>
          </button>
          <button onClick={() => { 
              const creds = `*Income Tax Credentials*\n*Entity:* ${selectedClient!.legalName}\n*PAN:* ${selectedClient!.itProfile?.pan}\n*Password:* ${selectedClient!.itProfile?.password}`;
              shareViaWhatsApp(creds);
