                <th className="px-[5.5px] py-3 text-[14px] font-bold uppercase tracking-widest text-slate-900 w-[120px] text-center relative">
                   <div className="flex items-center justify-center gap-1">
                      GSTR-3B
                      <button disabled={!isQuarterEnd} onClick={() => setIsR3bFilterOpen(!isR3bFilterOpen)} className={`p-1 hover:bg-slate-200 rounded transition-colors ${!isQuarterEnd ? 'opacity-20 cursor-not-allowed' : ''}`}><svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg></button>
                   </div>
                   {isR3bFilterOpen && isQuarterEnd && (
                    <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1 w-32 bg-white border border-slate-200 rounded-xl shadow-xl z-[400] p-1 animate-in zoom-in-95">
                      {['All', 'Filed', 'Pending'].map(f => (
                        <button key={f} onClick={() => { setR3bFilter(f as any); setIsR3bFilterOpen(false); }} className={`w-full text-left px-3 py-2 text-[9px] font-black uppercase rounded-lg ${r3bFilter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>{f}</button>
                      ))}
                    </div>
                  )}
