export default ITClientFormModal;

import { useState, useCallback } from 'react';

export type RefundStatus = 'Pending' | 'Processed' | 'Issued' | 'Adjusted' | 'Rejected' | 'N/A';

export interface ITRFilingStatus {
  filed: boolean;
  date?: string;
  refundStatus?: RefundStatus;
  itrFile?: string; // Base64 or Blob URL
  compFile?: string; // Base64 or Blob URL
}

const STORAGE_KEY = 'clientify_itr_filing_data_v2';
const STORAGE_KEY_DATES = 'clientify_itr_due_dates_v1';

export const useITRReturnLogic = (selectedAY: string) => {
  const [allData, setAllData] = useState<Record<string, Record<string, ITRFilingStatus>>>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : {};
  });

  const [dueDates, setDueDates] = useState<Record<string, string>>(() => {
    const saved = localStorage.getItem(STORAGE_KEY_DATES);
    return saved ? JSON.parse(saved) : {};
  });

  const toggleStatus = useCallback((clientId: string) => {
    setAllData(prev => {
      const yearData = { ...(prev[selectedAY] || {}) };
      const clientData = { ...(yearData[clientId] || { filed: false, refundStatus: 'N/A' }) };

      clientData.filed = !clientData.filed;
      if (clientData.filed) {
        clientData.date = new Date().toISOString().split('T')[0];
        if (!clientData.refundStatus || clientData.refundStatus === 'N/A') {
          clientData.refundStatus = 'Pending';
        }
      } else {
        delete clientData.date;
        clientData.refundStatus = 'N/A';
      }

      yearData[clientId] = clientData;
      const next = { ...prev, [selectedAY]: yearData };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      return next;
    });
  }, [selectedAY]);

  const updateFilingDate = useCallback((clientId: string, date: string) => {
    setAllData(prev => {
      const yearData = { ...(prev[selectedAY] || {}) };
      const clientData = { ...(yearData[clientId] || { filed: true, refundStatus: 'Pending' }) };
      clientData.date = date;
      yearData[clientId] = clientData;
      const next = { ...prev, [selectedAY]: yearData };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      return next;
    });
  }, [selectedAY]);

  const cycleRefundStatus = useCallback((clientId: string) => {
    const statusFlow: RefundStatus[] = ['Pending', 'Processed', 'Issued', 'Adjusted', 'Rejected', 'N/A'];
    setAllData(prev => {
      const yearData = { ...(prev[selectedAY] || {}) };
      const clientData = { ...(yearData[clientId] || { filed: false, refundStatus: 'N/A' }) };
      const currentIdx = statusFlow.indexOf(clientData.refundStatus || 'N/A');
      const nextIdx = (currentIdx + 1) % statusFlow.length;
      clientData.refundStatus = statusFlow[nextIdx];

      yearData[clientId] = clientData;
      const next = { ...prev, [selectedAY]: yearData };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      return next;
    });
  }, [selectedAY]);

  const updateFileData = useCallback((clientId: string, type: 'itrFile' | 'compFile', base64: string | null) => {
    setAllData(prev => {
      const yearData = { ...(prev[selectedAY] || {}) };
      const clientData = { ...(yearData[clientId] || { filed: false }) };

      if (base64) {
        clientData[type] = base64;
      } else {
        delete clientData[type];
      }

      yearData[clientId] = clientData;
      const next = { ...prev, [selectedAY]: yearData };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      return next;
    });
  }, [selectedAY]);

  const getStatus = useCallback((clientId: string): ITRFilingStatus => {
    return (allData[selectedAY] || {})[clientId] || { filed: false, refundStatus: 'N/A' };
  }, [allData, selectedAY]);

  const updateDueDate = (val: string) => {
    const next = { ...dueDates, [selectedAY]: val };
    setDueDates(next);
    localStorage.setItem(STORAGE_KEY_DATES, JSON.stringify(next));
  };

  const getDueDate = () => dueDates[selectedAY] || '';

  return { getStatus, toggleStatus, updateFilingDate, cycleRefundStatus, updateFileData, updateDueDate, getDueDate };
};

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { Client } from '../../../types';
import { api } from '../../../services/api.ts';
import Loader from '../../../components/Loader';
import { useITRReturnLogic, RefundStatus } from './ITRReturnlogic';
import { YEARS } from '../GSTReturn/filinglogic/MonthlyFilingLogic';

const ITRReturn: React.FC = () => {
  const getPreviousAY = () => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();
    const startYear = currentMonth >= 3 ? currentYear : currentYear - 1;
    return `${startYear}-${(startYear + 1).toString().slice(-2)}`;
  };

  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedAY, setSelectedAY] = useState(getPreviousAY());
  const [statusFilter, setStatusFilter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [isFilterOpen, setIsFilterOpen] = useState(false);

  // Modals & Tools
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isLoginBoxOpen, setIsLoginBoxOpen] = useState(false);
  const [visiblePasswords, setVisiblePasswords] = useState<Set<string>>(new Set());

  const [editingPasswordId, setEditingPasswordId] = useState<string | null>(null);
  const [newPasswordValue, setNewPasswordValue] = useState('');

  // Actions Menu State
  const [activeActionsId, setActiveActionsId] = useState<string | null>(null);
  const [menuPosition, setMenuPosition] = useState({ top: 0, left: 0 });
  const actionsRef = useRef<HTMLDivElement>(null);

  const { getStatus, toggleStatus, updateFilingDate, cycleRefundStatus, updateDueDate, getDueDate } = useITRReturnLogic(selectedAY);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await api.getClients();
      // Automatically show all active IT clients
      setClients(data.filter(c => !!c.itProfile && (c.status === 'Active' || c.status === 'Active Filing')));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchClients(); }, []);

  useEffect(() => {
    const handleClose = (event: any) => {
      if (actionsRef.current && !actionsRef.current.contains(event.target as Node)) {
        setActiveActionsId(null);
      }
    };
    if (activeActionsId) document.addEventListener('mousedown', handleClose);
    return () => document.removeEventListener('mousedown', handleClose);
  }, [activeActionsId]);

  const getClientDisplayId = useCallback((client: Client) => {
    const itGroup = clients.slice().sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));
    const rank = itGroup.findIndex(c => c.id === client.id) + 1;
    return `IT/${rank.toString().padStart(2, '0')}`;
  }, [clients]);

  const filteredClients = useMemo(() => {
    let list = clients.filter(c => 
      (c.legalName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.itProfile?.pan || '').toLowerCase().includes(search.toLowerCase()) ||
      (c.itProfile?.fatherName || '').toLowerCase().includes(search.toLowerCase())
    );
    if (statusFilter !== 'All') {
      list = list.filter(c => statusFilter === 'Filed' ? getStatus(c.id).filed : !getStatus(c.id).filed);
    }
    return list;
  }, [clients, search, statusFilter, getStatus]);

  const handleExport = () => {
    const headers = ["ID", "Name", "Father Name", "Status", "Filing Date", "Refund Status", "PAN", "Password"].join(",");
    const rows = filteredClients.map(c => {
      const s = getStatus(c.id);
      return [
        getClientDisplayId(c),
        c.legalName,
        c.itProfile?.fatherName,
        s.filed ? 'Filed' : 'Pending',
        s.date || '---',
        s.refundStatus || 'N/A',
        c.itProfile?.pan,
        c.itProfile?.password
      ].map(v => `"${v || ''}"`).join(",");
    }).join("\n");
    const blob = new Blob([headers + "\n" + rows], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = `ITR_Return_${selectedAY}.csv`; a.click();
  };

  const openActionsMenu = (e: React.MouseEvent, client: Client) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setMenuPosition({ top: rect.bottom + window.scrollY + 8, left: rect.right - 256 });
    setActiveActionsId(client.id);
    setSelectedClient(client);
  };

  const saveQuickPassword = async (client: Client) => {
    try {
      const updated = { ...client, itProfile: { ...client.itProfile!, password: newPasswordValue } };
      await api.saveClient(updated);
      setClients(prev => prev.map(c => c.id === client.id ? (updated as Client) : c));
      setEditingPasswordId(null);
    } catch (err) { alert("Update failed."); }
  };

  const getRefundColor = (st?: RefundStatus) => {
    switch (st) {
      case 'Issued': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case 'Processed': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'Adjusted': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'Rejected': return 'bg-rose-100 text-rose-700 border-rose-200';
      case 'Pending': return 'bg-indigo-50 text-indigo-700 border-indigo-100';
      default: return 'bg-slate-50 text-slate-300 border-slate-100';
    }
  };

  const shareViaWhatsApp = (text: string) => {
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

